cat > probe_unix_test.go <<'EOF'
package main

import (
	"encoding/json"
	"testing"
	"time"
)

func TestProbeUnixTimestamps(t *testing.T) {
	store := NewStore(time.Minute)
	at := time.Unix(1700000000, 0)
	store.now = func() time.Time { return at }
	session := store.Create("s1", "alice")

	data, err := json.Marshal(session)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var wire map[string]any
	if err := json.Unmarshal(data, &wire); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	created, ok := wire["Created"].(float64)
	if !ok {
		t.Fatalf("Created is not a JSON number: %v", wire["Created"])
	}
	if int64(created) != 1700000000 {
		t.Fatalf("Created = %v, want unix seconds 1700000000", wire["Created"])
	}
	lastSeen, ok := wire["LastSeen"].(float64)
	if !ok {
		t.Fatalf("LastSeen is not a JSON number: %v", wire["LastSeen"])
	}
	if int64(lastSeen) != 1700000000 {
		t.Fatalf("LastSeen = %v, want unix seconds", wire["LastSeen"])
	}
	if _, hasID := wire["ID"]; !hasID {
		t.Fatal("ID field missing")
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_unix_test.go ; exit $rc

